use pfx_vector_core::{Angle,Transform2D};
use crate::{SvgDiagnostic,SvgError};
fn parse_numbers(s:&str)->Result<Vec<f64>,SvgError>{let normalized=s.replace(','," ");normalized.split_whitespace().map(|v|v.parse::<f64>().map_err(|_|SvgError{diagnostic:SvgDiagnostic{message:"invalid transform number".into(),start:0,end:s.len()}})).collect()}
pub fn parse_transform(input:&str)->Result<Transform2D,SvgError>{let mut rest=input.trim();let mut out=Transform2D::identity();while !rest.is_empty(){let open=rest.find('(').ok_or_else(||SvgError{diagnostic:SvgDiagnostic{message:"expected transform (".into(),start:0,end:rest.len().min(1)}})?;let name=rest[..open].trim();let after=&rest[open+1..];let close=after.find(')').ok_or_else(||SvgError{diagnostic:SvgDiagnostic{message:"expected transform )".into(),start:open,end:rest.len()}})?;let vals=parse_numbers(&after[..close])?;let t=match name{"matrix" if vals.len()==6=>Transform2D::new(vals[0],vals[1],vals[2],vals[3],vals[4],vals[5]),"translate" if vals.len()==1||vals.len()==2=>Transform2D::translation(vals[0],*vals.get(1).unwrap_or(&0.0)),"scale" if vals.len()==1||vals.len()==2=>Transform2D::scale(vals[0],*vals.get(1).unwrap_or(&vals[0])),"rotate" if vals.len()==1=>Transform2D::rotation(Angle::degrees(vals[0])),"rotate" if vals.len()==3=>Transform2D::translation(vals[1],vals[2]).then(Transform2D::rotation(Angle::degrees(vals[0]))).then(Transform2D::translation(-vals[1],-vals[2])),"skewX" if vals.len()==1=>Transform2D::skew_x(Angle::degrees(vals[0])),"skewY" if vals.len()==1=>Transform2D::skew_y(Angle::degrees(vals[0])),_=>return Err(SvgError{diagnostic:SvgDiagnostic{message:"unsupported transform syntax".into(),start:0,end:open}})};out=out.then(t);rest=after[close+1..].trim_start_matches(|c:char|c.is_whitespace()||c==',');}Ok(out)}
